# Reproduce the seven conversation models with Blender 4.3+:
# blender --background --python scripts/build-companion-rigs.py -- fox
# Shared facial construction is derived from the approved capybara v3 prototype.
# The shipped capybara model is deliberately never regenerated by this script.
import bpy,math,random,json,sys
from pathlib import Path
from mathutils import Vector
random.seed(37)
ROOT=Path(__file__).resolve().parents[1]
KIND=sys.argv[sys.argv.index('--')+1] if '--' in sys.argv else 'fox'
CONFIG={
 'bird':((.16,.32,.70),(.93,.83,.61),(.12,.24,.57)),
 'fox':((.82,.25,.055),(.95,.86,.70),(.22,.065,.028)),
 'cat':((.37,.29,.43),(.91,.80,.73),(.60,.30,.38)),
 'dog':((.78,.49,.17),(.91,.66,.30),(.66,.36,.10)),
 'guinea-pig':((.93,.84,.69),(.95,.87,.76),(.62,.27,.25)),
 'quokka':((.60,.32,.115),(.78,.53,.29),(.37,.17,.075)),
 'panda':((.94,.88,.76),(.97,.92,.83),(.045,.035,.032))
}
BASE,MUZZLE,INNER=CONFIG[KIND]
OUT=ROOT/'public'/'companions-3d';OUT.mkdir(exist_ok=True)
bpy.ops.object.select_all(action='SELECT');bpy.ops.object.delete(use_global=False)
scene=bpy.context.scene
scene.render.engine='CYCLES';scene.cycles.samples=128;scene.cycles.use_denoising=False
scene.render.threads_mode='FIXED';scene.render.threads=6
scene.render.resolution_x=480;scene.render.resolution_y=600;scene.render.resolution_percentage=100
scene.render.film_transparent=False;scene.render.fps=24;scene.frame_start=1;scene.frame_end=288
scene.world.color=(.10,.15,.12)
scene.view_settings.view_transform='AgX';scene.view_settings.look='AgX - Medium High Contrast'

def material(name,color,rough=.6,noise=0,bump=.03):
 m=bpy.data.materials.new(name);m.diffuse_color=(*color,1);m.use_nodes=True
 bs=m.node_tree.nodes.get('Principled BSDF');bs.inputs['Base Color'].default_value=(*color,1);bs.inputs['Roughness'].default_value=rough
 if noise:
  tex=m.node_tree.nodes.new('ShaderNodeTexNoise');tex.inputs['Scale'].default_value=noise;tex.inputs['Detail'].default_value=2.5
  b=m.node_tree.nodes.new('ShaderNodeBump');b.inputs['Strength'].default_value=.3;b.inputs['Distance'].default_value=bump
  m.node_tree.links.new(tex.outputs['Fac'],b.inputs['Height']);m.node_tree.links.new(b.outputs['Normal'],bs.inputs['Normal'])
 return m
gold=material('Species short fur skin',BASE,.88,155,.006)
chinmat=material('Warm cheek undercoat',(.74,.40,.13),.88,150,.015)
muzzle=material('Soft species muzzle',MUZZLE,.88,125,.004)
earmat=material('Warm inner ear',INNER,.92,90,.004)
dark=material('Lip and nostril',(.067,.022,.014),.67)
cavitymat=material('Mouth interior',(.055,.007,.009),.92)
tonguemat=material('Tongue',(.55,.12,.14),.65)
purple=material('Plum woven scarf',(.23,.025,.16),.86,180,.009)
embroidery=material('Gold wheat thread',(.87,.53,.12),.5,90,.005)
sclera=material('Warm dark eye rim',(.07,.035,.02),.42)
iris=material('Deep amber iris',(.025,.014,.008),.30)
pupil=material('Dark glossy pupil',(.018,.009,.005),.24)
for m in [iris,pupil]:m.node_tree.nodes.get('Principled BSDF').inputs['Coat Weight'].default_value=.20
furmats=[material('Fur strand '+str(i),tuple(min(1,v*f) for v in BASE),.88) for i,f in enumerate([.95,1.07,.87,1.15])]
parts=[]
def smooth(o):
 for p in o.data.polygons:p.use_smooth=True
 return o
def mesh(name,verts,faces,mat):
 me=bpy.data.meshes.new(name+' geometry');me.from_pydata(verts,[],faces);me.update();o=bpy.data.objects.new(name,me);scene.collection.objects.link(o);o.data.materials.append(mat);smooth(o);return o
def ball(name,pos,scale,mat,segments=36,rings=24):
 bpy.ops.mesh.primitive_uv_sphere_add(segments=segments,ring_count=rings,location=pos);o=bpy.context.object;o.name=name;o.scale=scale
 bpy.ops.object.transform_apply(location=False,rotation=False,scale=True);o.data.materials.append(mat);smooth(o);return o
def line(name,pts,radius,mat,closed=False):
 cu=bpy.data.curves.new(name,'CURVE');cu.dimensions='3D';cu.bevel_depth=radius;cu.bevel_resolution=3;cu.resolution_u=16
 sp=cu.splines.new('BEZIER');sp.bezier_points.add(len(pts)-1)
 for p,co in zip(sp.bezier_points,pts):p.co=co;p.handle_left_type='AUTO';p.handle_right_type='AUTO'
 sp.use_cyclic_u=closed;o=bpy.data.objects.new(name,cu);scene.collection.objects.link(o);o.data.materials.append(mat)
 bpy.context.view_layer.objects.active=o;o.select_set(True);bpy.ops.object.convert(target='MESH');o.select_set(False);return o
def register(o,bone='head'):parts.append((o,bone));return o

# A custom continuous head surface, broader at the cheeks than at the crown.
verts=[];faces=[];nu,nv=64,48
def headpoint(theta,phi):
 z=math.cos(theta);r=math.sin(theta);cheek=1+.18*max(0,-z)
 return Vector((1.025*r*math.cos(phi)*cheek,.67*r*math.sin(phi),2.12+.84*z))
for j in range(nv+1):
 for i in range(nu):verts.append(headpoint(math.pi*j/nv,2*math.pi*i/nu))
for j in range(nv):
 for i in range(nu):a=j*nu+i;b=j*nu+(i+1)%nu;faces.append((a,b,b+nu,a+nu))
head=register(mesh('Sculpted broad capybara head',verts,faces,gold))
# An actual oral opening is carved into the head. A facial morph closes the
# opening to a seam; the dark interior sits behind the surface, not on it.
cutter=ball('Temporary oral volume',(0,-.60,1.71),(.28,.32,.11),dark,48,32)
boolean=head.modifiers.new('Oral cavity','BOOLEAN');boolean.operation='DIFFERENCE';boolean.object=cutter
bpy.context.view_layer.objects.active=head;head.select_set(True);bpy.ops.object.modifier_apply(modifier=boolean.name);head.select_set(False);bpy.data.objects.remove(cutter,do_unlink=True)
head.shape_key_add(name='Basis');headopen=head.shape_key_add(name='MouthOpen')
for p in head.data.shape_keys.key_blocks['Basis'].data:
 if p.co.y<-.36 and (p.co.x/.34)**2+((p.co.z-1.71)/.19)**2<1.15:
  p.co.z=1.71+(p.co.z-1.71)*.04
  zn=(p.co.z-2.12)/.84;cheek=1+.18*max(0,-zn)
  p.co.y=-.67*math.sqrt(max(.02,1-(p.co.x/(1.025*cheek))**2-zn**2))
# Neck and shoulder bust stay modest: this trial is about face and neck control.
register(ball('Neck', (0,.05,1.02),(.53,.47,.52),gold),'neck')
register(ball('Shoulder bust',(0,.13,.63),(.84,.45,.50),gold),'neck')
# Species silhouettes use the same facial rig with individually authored anatomy.
def pointed_ear(side):
 # Rounded triangular shell and inset, with a substantial soft base.
 x=side*.69
 for label,mat,scale,y in [('outer',gold,1,.06),('inner',earmat,.63,-.09)]:
  vs=[(x-side*.30*scale,y,2.68),(x+side*.29*scale,y,2.68),(x+side*.11*scale,y,2.68+.65*scale),
      (x,y+.24*scale,2.90)]
  o=register(mesh(f'{KIND} {label} pointed ear {side}',vs,[(0,1,2),(0,3,1),(1,3,2),(2,3,0)],mat))
  bevel=o.modifiers.new('Soft ear corners','BEVEL');bevel.width=.075*scale;bevel.segments=4
  bpy.context.view_layer.objects.active=o;bpy.ops.object.modifier_apply(modifier=bevel.name)
for side in [-1,1]:
 if KIND in ['fox','cat']:pointed_ear(side)
 elif KIND=='dog':
  ear=register(ball('Long floppy dog ear '+str(side),(side*1.02,-.20,2.18),(.25,.20,.57),earmat));ear.rotation_euler.y=side*.15
 elif KIND=='guinea-pig':
  ear=register(ball('Folded guinea pig ear '+str(side),(side*.84,.015,2.69),(.25,.12,.18),earmat));ear.rotation_euler.y=side*.38
 elif KIND!='bird':
  register(ball('Round ear '+str(side),(side*.78,.055,2.79),(.24,.135,.25),earmat if KIND=='panda' else gold))
  if KIND!='panda':register(ball('Inner round ear '+str(side),(side*.78,-.074,2.80),(.15,.028,.17),earmat))
if KIND=='bird':
 beakmat=material('Honey gold beak',(.70,.32,.055),.72)
 register(mesh('Upper curved bird beak',[(-.27,-.59,2.12),(.27,-.59,2.12),(0,-1.02,1.89),(-.23,-.60,1.80),(.23,-.60,1.80),(0,-.68,2.20)],[(0,5,1),(0,2,5),(5,2,1),(0,3,2),(1,2,4),(2,3,4),(0,1,4,3)],beakmat))
 register(mesh('Lower bird beak',[(-.23,-.60,1.73),(.23,-.60,1.73),(0,-.96,1.78),(0,-.65,1.62)],[(0,1,2),(0,3,1),(0,2,3),(1,3,2)],beakmat),'jaw')
 for i in range(3):
  tuft=register(ball('Blue feather crest '+str(i),(-.20+i*.18,.07,2.94+(.09 if i==1 else 0)),(.25,.13,.10),gold));tuft.rotation_euler.y=-.24
else:
 # Paired cream muzzle pads and a small animal nose preserve the friendly face.
 for side in [-1,1]:register(ball('Soft muzzle pad '+str(side),(side*.17,-.615,1.98),(.24,.20,.22),muzzle))
 nose=earmat if KIND=='guinea-pig' else dark
 register(ball('Small rounded nose',(0,-.806,2.105),(.115,.043,.072),nose))
 register(line('Small smile stem',[(0,-.81,2.08),(0,-.81,2.02),(0,-.78,1.91)],.006,dark))

if KIND=='bird':
 for o,b in parts:
  if 'bird beak' in o.name:
   bevel=o.modifiers.new('Rounded beak edges','BEVEL');bevel.width=.065;bevel.segments=3
   bpy.context.view_layer.objects.active=o;bpy.ops.object.modifier_apply(modifier=bevel.name)

# Jaw is a separate rigid/skinned component with its own actual rotation pivot.
lip=register(ball('Soft lower jaw lip',(0,-.565,1.695),(.255,.028,.022),gold),'jaw')
lowerline=register(line('Lower lip contour',[(-.24,-.586,1.735),(-.13,-.597,1.71),(0,-.604,1.704),(.13,-.597,1.71),(.24,-.586,1.735)],.003,dark),'jaw')
mouth=register(ball('Mouth cavity',(0,-.42,1.71),(.245,.12,.105),cavitymat))
openkey=headopen
tongue=register(ball('Tongue',(0,-.55,1.67),(.12,.018,.024),tonguemat),'jaw')
tongue.shape_key_add(name='Basis');tonguekey=tongue.shape_key_add(name='TongueVisible')
for p in tongue.data.shape_keys.key_blocks['Basis'].data:p.co*=.01

lidkeys=[]
def make_lid(name,center,side,upper):
 # Front elliptical shell covers the eyeball as a morph target, rather than
 # shrinking the pupil. Both lids meet on a shared curved seam when closed.
 nx,ny=40,10;rx,ry,rz=.145,.132,.178
 def coords(threshold):
  out=[]
  for j in range(ny+1):
   t=j/ny
   for i in range(nx+1):
    x=-1+2*i/nx;height=math.sqrt(max(0,1-x*x))
    z=(threshold+(1-threshold)*t)*height if upper else (-1+(threshold+1)*t)*height
    y=-math.sqrt(max(.0001,1-x*x-z*z))
    out.append((center[0]+rx*x,center[1]+ry*y-.012,center[2]+rz*z))
  return out
 base=coords(.80 if upper else -.84);closed=coords(-.08)
 fs=[]
 for j in range(ny):
  for i in range(nx):a=j*(nx+1)+i;fs.append((a,a+1,a+nx+2,a+nx+1))
 o=register(mesh(name,base,fs,gold));o.shape_key_add(name='Basis');k=o.shape_key_add(name='Blink')
 for p,co in zip(k.data,closed):p.co=co
 lidkeys.append(k);return o
for side in [-1,1]:
 cx,cy,cz=side*.54,-.48,2.405
 register(ball('Eye ivory '+str(side),(cx,cy,cz),(.14,.080,.17),sclera),f'eye.{side}')
 register(ball('Amber iris '+str(side),(cx,-.537,cz),(.12,.025,.15),iris),f'eye.{side}')
 register(ball('Pupil '+str(side),(cx,-.566,cz+.007),(.092,.010,.118),pupil),f'eye.{side}')
 # Deliberate illustration-style highlights make the small dark eyes warm.
 glintmat=bpy.data.materials.get('Soft eye highlight') or material('Soft eye highlight',(.96,.90,.76),.20)
 register(ball('Eye highlight '+str(side),(cx-.029,-.580,cz+.046),(.022,.006,.024),glintmat,24,16),f'eye.{side}')
 register(ball('Eye small highlight '+str(side),(cx+.029,-.578,cz-.039),(.008,.004,.009),glintmat,16,12),f'eye.{side}')
 make_lid('Upper eyelid '+str(side),(cx,cy,cz),side,True);make_lid('Lower eyelid '+str(side),(cx,cy,cz),side,False)
 pts=[(cx-.12,-.57,2.65),(cx,-.594,2.69),(cx+.12,-.57,2.65)]
 register(line('Expressive eyebrow '+str(side),pts,.013,muzzle))

# Soft color, following the cheek surface rather than separate cheek balls.
blushmat=material('Soft coral cheek tint',BASE,.9)
node=blushmat.node_tree.nodes.new('ShaderNodeVertexColor');node.layer_name='CheekColor'
blushmat.node_tree.links.new(node.outputs['Color'],blushmat.node_tree.nodes.get('Principled BSDF').inputs['Base Color'])
for side in [-1,1]:
 bv=[];bf=[];colors=[];rings,sectors=6,40
 for j in range(rings+1):
  r=j/rings
  for i in range(sectors):
   a=math.tau*i/sectors;x=side*.69+.14*r*math.cos(a);z=2.10+.058*r*math.sin(a);zn=(z-2.12)/.84;cheek=1+.18*max(0,-zn)
   y=-.67*math.sqrt(max(.02,1-(x/(1.025*cheek))**2-zn**2))-.005
   bv.append((x,y,z));w=(1-r*r)**2*.7;colors.append(tuple((1-w)*v+w*t for v,t in zip(BASE,tuple(.8*v+.2*t for v,t in zip(BASE,(.86,.24,.15)))))+(1,))
 for j in range(rings):
  for i in range(sectors):a=j*sectors+i;b=j*sectors+(i+1)%sectors;bf.append((a,b,b+sectors,a+sectors))
 o=register(mesh('Rosy cheek '+str(side),bv,bf,blushmat));attr=o.data.color_attributes.new(name='CheekColor',type='FLOAT_COLOR',domain='POINT')
 for v,c in zip(attr.data,colors):v.color=c

if KIND=='guinea-pig':
 # Cream-based cheek decals would mask the two contrasting coat patches.
 for o,b in parts[:]:
  if o.name.startswith('Rosy cheek'):
   parts.remove((o,b));bpy.data.objects.remove(o,do_unlink=True)

# Species markings follow the continuous head surface, including short fur.
cream=material('Cream chest and facial mask',MUZZLE,.88)
mark=material('Species dark markings',(.045,.033,.030) if KIND=='panda' else (.17,.095,.17) if KIND=='cat' else (.20,.075,.028),.88)
orange=material('Guinea pig ginger patches',(.71,.28,.06),.88)
def region(p):
 x,y,z=p
 if KIND in ['bird','fox'] and z<2.11 and y<-.10:return 1
 if KIND=='cat' and y<-.15:
  if z<1.96:return 1
  if z>2.67 and abs(x)<.38 and abs((abs(x)-.13))<.052:return 2
  if abs(x)>.68 and 2.02<z<2.65 and int((z-2.02)/.105)%2==0:return 2
 if KIND=='guinea-pig':
  if x<-.18:return 3
  if x>.55:return 2
 return 0
for mat in [cream,mark,orange]:head.data.materials.append(mat)
for poly in head.data.polygons:
 center=sum((head.data.vertices[i].co for i in poly.vertices),Vector())/len(poly.vertices)
 poly.material_index=region(center)
if KIND=='panda':
 for side in [-1,1]:
  patch=register(ball('Panda eye patch '+str(side),(side*.54,-.465,2.405),(.235,.10,.275),mark));patch.rotation_euler.y=side*.23
 register(ball('Cream panda chest',(0,-.25,.65),(.68,.24,.43),cream),'neck')
if KIND=='cat':
 for side in [-1,1]:
  for i in range(3):
   z=2.0+i*.085
   register(line('Cat whisker '+str(side)+' '+str(i),[(side*.32,-.78,z),(side*.60,-.67,z+.005),(side*.82,-.49,z+.035)],.008,mark))
if KIND in ['bird','fox','dog','guinea-pig','quokka']:
 register(ball('Soft contrasting chest',(0,-.27,.70),(.58,.24,.38),cream),'neck')

# Mesh ribbons are actual geometry, shared with the exported model. Dense short
# strands follow the head's surface; no image plane or prerecorded clip is used.
v=[];f=[];mids=[]
for n in range(6500):
 z=random.uniform(-1,1);theta=math.acos(z);phi=random.uniform(0,math.tau);p=headpoint(theta,phi)
 if p.y<-.26:
  if any(((p.x-s*.54)/.19)**2+((p.z-2.405)/.24)**2<1.12 for s in [-1,1]):continue
  if (p.x/.56)**2+((p.z-1.955)/.45)**2<1.2:continue
 normal=Vector((p.x/1.025**2,p.y/.67**2,(p.z-2.12)/.84**2)).normalized()
 direction=Vector((p.x*.30,-.10,-1.0));tangent=(direction-normal*direction.dot(normal)).normalized()
 length=random.uniform(.014,.030);width=random.uniform(.00085,.0015)
 across=normal.cross(tangent).normalized()*width;tip=p+normal*length*.46+tangent*length*.75
 mid=p+(tip-p)*.55+normal*length*.15
 index=len(v);v.extend([p-across,p+across,mid+across*.65,mid-across*.65,tip]);f.extend([(index,index+1,index+2,index+3),(index+3,index+2,index+4)]);mids.extend([random.choices(range(4),[5,3,2,1])[0]]*2)
fur=register(mesh('Combed short golden fur',v,f,furmats[0]))
for mat in furmats[1:]:fur.data.materials.append(mat)
for mat in [cream,mark,orange]:fur.data.materials.append(mat)
for p,mi in zip(fur.data.polygons,mids):
 center=sum((fur.data.vertices[i].co for i in p.vertices),Vector())/len(p.vertices)
 zone=region(center);p.material_index=mi if zone==0 else len(furmats)+zone-1

# A compact purple bandana and wheat crest preserve the character cue.
register(ball('Bandana collar',(0,-.01,1.14),(.60,.48,.105),purple),'neck')
vs=[];fs=[];rows,cols=16,24
for j in range(rows+1):
 t=j/rows;half=.60*(1-t)+.018
 for i in range(cols+1):
  u=-1+2*i/cols;vs.append((u*half,-.43-.11*(1-u*u)-.035*math.sin(t*math.pi),1.10-.62*t+.05*u*u))
for j in range(rows):
 for i in range(cols):a=j*(cols+1)+i;fs.append((a,a+1,a+cols+2,a+cols+1))
scarf=register(mesh('Draped triangular bandana',vs,fs,purple),'neck')
sol=scarf.modifiers.new('Cloth thickness','SOLIDIFY');sol.thickness=.018
register(line('Bandana sewn edge',[(-.59,-.435,1.11),(0,-.56,.47),(.59,-.435,1.11)],.009,muzzle),'neck')
for side in [-1,1]:
 register(line('Wheat stem '+str(side),[(0,-.573,.62),(side*.10,-.575,.74),(side*.20,-.552,.94)],.008,embroidery),'neck')
 for i in range(4):
  x=side*(.04+i*.040);z=.69+i*.065
  leaf=register(ball('Embroidered wheat grain',(x,-.585,z),(.017,.009,.044),embroidery,20,12),'neck');leaf.rotation_euler.y=side*.65

for o,b in parts:
 if b=='neck' and o.name not in ['Neck','Shoulder bust']:o.location.z+=.11

# Species-specific skull proportions also transform facial targets together;
# head/jaw/eye rest pivots are adjusted below, keeping the shared rig contract.
SX,SZ={'bird':(.89,1.02),'fox':(.91,.96),'cat':(.91,.98),'dog':(.95,1.0),'guinea-pig':(.96,1.02),'quokka':(.90,1.02),'panda':(.99,1.02)}[KIND]
for o,b in parts:
 if b=='neck':continue
 o.location.x*=SX;o.location.z=2.12+(o.location.z-2.12)*SZ
 if o.data.shape_keys:
  for key in o.data.shape_keys.key_blocks:
   for v in key.data:v.co.x*=SX;v.co.z*=SZ
 else:
  for v in o.data.vertices:v.co.x*=SX;v.co.z*=SZ

# One skeleton drives the same model in all states; all rendered meshes use
# explicit vertex groups, so jaw and head motion survive portable GLB export.
arm=bpy.data.armatures.new('Capybara facial skeleton');rig=bpy.data.objects.new('ContinuumCapybaraRig',arm);scene.collection.objects.link(rig)
bpy.context.view_layer.objects.active=rig;rig.select_set(True);bpy.ops.object.mode_set(mode='EDIT')
def bone(name,head,tail,parent=None):
 b=arm.edit_bones.new(name)
 if name!='neck':
  head=(head[0]*SX,head[1],2.12+(head[2]-2.12)*SZ);tail=(tail[0]*SX,tail[1],2.12+(tail[2]-2.12)*SZ)
 b.head=head;b.tail=tail
 if parent:b.parent=arm.edit_bones[parent]
bone('neck',(0,0,.65),(0,0,1.23));bone('head',(0,0,1.23),(0,0,2.45),'neck');bone('jaw',(0,-.06,1.66),(0,-.06,1.96),'head')
for side in [-1,1]:bone(f'eye.{side}',(side*.54,-.48,2.405),(side*.54,-.48,2.60),'head')
bpy.ops.object.mode_set(mode='OBJECT');rig.select_set(False)
for o,b in parts:
 vg=o.vertex_groups.new(name=b);vg.add(list(range(len(o.data.vertices))),1.,'REPLACE');mod=o.modifiers.new('Facial rig','ARMATURE');mod.object=rig

# Neutral portable models have no demonstration audio or baked animation clips.
# The production renderer drives jaw, eyes, lids and neck from audible playback.
rig.name='Continuum_'+KIND+'_FaceRig'
rig['companion']=KIND
scene.frame_set(1)
bpy.ops.object.select_all(action='DESELECT');rig.select_set(True)
for o,_ in parts:o.select_set(True)
bpy.context.view_layer.objects.active=rig
bpy.ops.export_scene.gltf(filepath=str(OUT/(KIND+'-pop-v1.glb')),export_format='GLB',use_selection=True,export_animations=False,export_skins=True,export_morph=True)
print('COMPANION_RIG_READY',KIND,flush=True)
